"""Vòng phản hồi — đọc board Trello TRƯỚC khi sinh ý, biến quyết định của người duyệt
thành tín hiệu cho lượt sau.

Người duyệt làm việc trên board, không làm việc với bộ não. Nên bộ não phải tự đọc board:
  * thẻ [2D] nằm ở list "đã duyệt" (Đợi Design / Designer nhận / Chờ Upload...)  → +1
  * thẻ [2D] bị archive                                                          → -1
  * thẻ [2D] còn nằm nguyên ở list ý tưởng quá N ngày không ai đụng               → 0 (tồn)

Chấm theo CHỦ THỂ, không theo tên thẻ: mỗi thẻ mang chữ ký ở dòng cuối
(`gritfell|species_canonical=musky|pose_canonical=...|art_slot=...`). Trích trường đầu
của chữ ký làm khoá chủ thể (loài với GritFell, device với GerberaPrints).

Kết quả ghi vào ideas/feedback/<brand>.json và được:
  * planner dùng để xếp ưu tiên tín hiệu (chủ thể được duyệt lên trước, bị bỏ xuống sau);
  * ledger dùng để đổi status proposed → approved / rejected (không xoá dòng, chỉ đổi trạng thái).

Không có Trello key = bỏ qua có báo, không chết job. Đọc được 0 thẻ [2D] = không ghi gì,
KHÔNG được coi là "mọi thứ bị bỏ".
"""
from __future__ import annotations
import json
import os
import re
import urllib.error
import urllib.parse
import urllib.request
import collections
from datetime import date, datetime, timezone
from pathlib import Path

from .signals import Signal
from .schema import canon
from .signals import _bo_dau

API = "https://api.trello.com/1"
SIG_RE = re.compile(r"chữ ký `([^`]+)`")


class FeedbackError(RuntimeError):
    pass


def _creds() -> tuple:
    k = os.environ.get("TRELLO_KEY", "").strip()
    t = os.environ.get("TRELLO_TOKEN", "").strip()
    if not k or not t:
        raise FeedbackError("Thiếu TRELLO_KEY / TRELLO_TOKEN — bỏ qua vòng phản hồi")
    return k, t


def _get(path: str, params: dict, timeout: int = 30):
    k, t = _creds()
    q = urllib.parse.urlencode({**params, "key": k, "token": t})
    req = urllib.request.Request(f"{API}{path}?{q}", headers={"User-Agent": "foxera-idea-feedback"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        raise FeedbackError(f"Trello HTTP {e.code} tại {path}: {e.read()[:200]!r}") from e
    except urllib.error.URLError as e:
        raise FeedbackError(f"Không gọi được Trello: {e.reason}") from e


def fetch_board_cards(board_short: str) -> tuple:
    """→ (lists {id: name}, cards[]) gồm cả thẻ đã archive (filter=all)."""
    lists = _get(f"/boards/{board_short}/lists", {"filter": "all", "fields": "name,closed"})
    cards = _get(f"/boards/{board_short}/cards", {"filter": "all",
                                                   "fields": "name,desc,idList,closed,dateLastActivity"})
    return {l["id"]: l["name"] for l in lists}, cards


def subject_of(sig_key: str) -> str | None:
    """'gritfell|species_canonical=musky|pose=...' → 'musky' (trường đầu tiên sau brand)."""
    parts = sig_key.split("|")
    if len(parts) < 2 or "=" not in parts[1]:
        return None
    return parts[1].split("=", 1)[1].strip().lower() or None


def _la_the_cua(card: dict, prefix: str) -> bool:
    """Thẻ của engine này: tên mang đúng tiền tố, HOẶC đã bị người đổi tên (không còn thẻ [..] nào).
    Tên mang tiền tố engine KHÁC (`[HAT]`…) thì không phải của mình dù chung chữ ký brand."""
    n = (card.get("name") or "").lstrip()
    if not prefix or n.startswith(prefix):
        return True
    return not n.startswith("[")


def merged_lists(tcfg: dict) -> dict:
    """feedback + history_lists gộp đúng như `pheu()` — để cổng nhịp, điểm chủ thể và phễu
    cùng một định nghĩa 'duyệt' / 'loại'. Hai bộ đếm hai định nghĩa là báo cáo giả."""
    fcfg = dict(tcfg.get("feedback") or {})
    hcfg = tcfg.get("history_lists") or {}
    fcfg["approved_lists"] = list(fcfg.get("approved_lists", [])) + list(hcfg.get("uploaded", []))
    fcfg["rejected_lists"] = list(fcfg.get("rejected_lists", [])) + list(hcfg.get("rejected", []))
    return fcfg


def classify(card: dict, list_name: str, cfg: dict, today: date) -> str:
    """→ 'approved' | 'rejected' | 'stale' | 'pending'."""
    if card.get("closed"):
        return "rejected"
    ln = list_name.lower()
    # 2.35.4: thẻ người đã KÉO sang list Loại mà chưa archive trước đây rơi xuống `return "pending"`
    # → 51 thẻ bị loại trên board Gerbera bị đếm là CHỜ, cổng nhịp đóng ở đúng 60, và chủ thể bị loại
    # được 0 điểm thay vì −1. `pheu()` đếm đúng từ lâu — hai bộ đếm lệch nhau. Nay dùng chung danh sách.
    if any(r.lower() in ln for r in cfg.get("rejected_lists", [])):
        return "rejected"
    if any(a.lower() in ln for a in cfg.get("approved_lists", [])):
        return "approved"
    if any(i.lower() in ln for i in cfg.get("idea_lists", [])):
        last = card.get("dateLastActivity", "")
        try:
            d = datetime.fromisoformat(last.replace("Z", "+00:00")).date()
        except ValueError:
            d = today
        if (today - d).days >= int(cfg.get("stale_after_days", 7)):
            return "stale"
        return "pending"
    return "pending"


def lich_su(brand, toi_thieu: int = 6) -> tuple[list, list]:
    """Đào LỊCH SỬ SẢN XUẤT trên board thành tín hiệu — không chỉ 11 thẻ engine đang đếm.

    Đo 17/09 trên board Kinmireva: **2.289 thẻ**, trong đó «Loại» 891 và «Uploaded» 101.
    Vòng phản hồi cũ chỉ thấy 11 vì nó lọc thẻ tiền tố `[EMB]` có sig_key. Cả kho quyết định
    THẬT của đội — cái gì từng lên shop, cái gì bị bỏ — nằm ngoài tầm nhìn của bộ não.

    Cách đo: tách từ khoá trong TÊN thẻ, so tỉ lệ xuất hiện ở nhóm lên-shop với nhóm bị-loại.
    Từ nào lệch ≥2 lần và đủ `toi_thieu` lần xuất hiện thì thành tín hiệu `HIST:` (dương hoặc âm).

    Hạn chế phải nói rõ: tên thẻ là MÃ (`12.05-F02-CAP7-CLONE`), và nằm ở list nào có thể phản ánh
    quy trình chứ không hẳn chất lượng. Nên tín hiệu này mang evidence HYPOTHESIS, không phải SIGNAL.
    """
    tcfg = brand.raw.get("trello") or {}
    hcfg = tcfg.get("history_lists") or {}
    if not hcfg or not tcfg.get("board"):
        return [], []
    lists, cards = fetch_board_cards(tcfg["board"])
    ten_list = {cid: (lists.get(cid) or "").lower() for cid in {c.get("idList") for c in cards}}
    dem = {"len": collections.Counter(), "bo": collections.Counter()}
    tong = {"len": 0, "bo": 0}
    for c in cards:
        ln = ten_list.get(c.get("idList"), "")
        nhom = ("len" if any(x.lower() in ln for x in hcfg.get("uploaded", []))
                else "bo" if any(x.lower() in ln for x in hcfg.get("rejected", [])) else None)
        if not nhom:
            continue
        tong[nhom] += 1
        for w in set(re.findall(r"[A-Za-z']{3,}", (c.get("name") or "").lower())):
            dem[nhom][w] += 1
    if tong["len"] < 20 or tong["bo"] < 20:
        return [], [f"· lịch sử board: mẫu quá nhỏ (lên {tong['len']}, bỏ {tong['bo']}) — chưa đủ để kết luận"]
    bo_qua = {"clone", "redesign", "newdesign", "design", "new", "final", "copy"}
    items = []
    for w in set(dem["len"]) | set(dem["bo"]):
        if w in bo_qua or dem["len"][w] + dem["bo"][w] < toi_thieu:
            continue
        p_len = dem["len"][w] / tong["len"] * 100
        p_bo = dem["bo"][w] / tong["bo"] * 100
        if p_len >= 2 * max(p_bo, 0.5):
            items.append(Signal(ref=f"HIST:{w}", kind="hook", label=w, evidence="HYPOTHESIS",
                                source=f"board {tcfg['board']} · lịch sử sản xuất", as_of="",
                                score=min(40.0, p_len - p_bo),
                                note=f"đội TỪNG đưa lên shop: '{w}' có ở {p_len:.0f}% thẻ đã upload vs {p_bo:.0f}% thẻ bị loại"))
        elif p_bo >= 2 * max(p_len, 0.5):
            items.append(Signal(ref=f"HIST:AVOID:{w}", kind="hook", label=f"tránh: {w}", evidence="HYPOTHESIS",
                                source=f"board {tcfg['board']} · lịch sử sản xuất", as_of="", score=-min(40.0, p_bo - p_len),
                                note=f"đội đã BỎ nhiều: '{w}' có ở {p_bo:.0f}% thẻ bị loại vs {p_len:.0f}% thẻ đã upload"))
    items.sort(key=lambda s: -abs(s.score or 0))
    items = items[:10]
    health = [f"· lịch sử board: {tong['len']} thẻ đã lên shop vs {tong['bo']} thẻ bị loại → {len(items)} tín hiệu HIST"]
    return items, health


# Dấu hiệu nhận ra một mô tả DO NGƯỜI VIẾT (bảng Kinmireva 17/09): có mục "Ý nghĩa", "Tại sao ... bán",
# "khách nào", "Có thể scale". Thẻ do engine sinh có "sinh tự động" + "chữ ký `" — loại ra.
_NGUOI_VIET = re.compile(r"(Ý nghĩa|Tại sao|khách nào|Có thể scale|Điểm mạnh|Vibe)", re.I)
_MAY_VIET = re.compile(r"sinh tự động .* engine|chữ ký `", re.I)
_SCALE = re.compile(r"(?:Có thể scale(?: thêm)?|biến thể bán tốt)[^\n]*\n((?:\s*-\s*.+\n?)+)", re.I)


def mau_nguoi(brand, min_desc: int = 600, gioi_han: int = 40) -> tuple[list, list, list]:
    """Đào các thẻ do NGƯỜI viết mô tả trên board — kho mẫu đạt mà bộ não chưa từng đọc.

    Đo 17/09: bảng Kinmireva có hàng trăm thẻ với mô tả tiếng Việt đầy đủ — ý nghĩa tổng thể, từng
    chi tiết, vì sao bán được trên Etsy, khách nào mua, vibe, TM/IP, và danh sách "Có thể scale thêm".
    Cấu trúc đó trùng 1:1 với các cổng mới của engine (recipient, emotion, mechanism, expansion) —
    người đã viết, máy chưa đọc.

    Trả (mẫu, tín hiệu BANK từ "Có thể scale thêm", health). Chỉ lấy thẻ ở list đã duyệt/đã lên
    (`history_lists.uploaded` + `feedback.approved_lists`) — mô tả hay mà thẻ bị loại thì không phải mẫu đạt.
    """
    tcfg = brand.raw.get("trello") or {}
    if not tcfg.get("board"):
        return [], [], []
    hcfg = tcfg.get("history_lists") or {}
    fcfg = tcfg.get("feedback") or {}
    dat = [x.lower() for x in hcfg.get("uploaded", []) + fcfg.get("approved_lists", [])]
    if not dat:
        return [], [], ["· mẫu người viết: cartridge chưa khai list đã duyệt/đã lên — không biết thẻ nào là mẫu đạt"]
    # 17/09: workspace «Zenda & FoxEra» có kho ý do người viết mà connector trong chat không thấy, nhưng
    # engine đi bằng TRELLO_KEY của user thì thấy. Khai thêm `extra_boards: [shortLink, ...]` là đọc được.
    boards = [tcfg["board"]] + list(tcfg.get("extra_boards") or [])
    lists, cards = {}, []
    for bs in boards:
        try:
            l2, c2 = fetch_board_cards(bs)
            lists.update(l2)
            cards += c2
        except Exception as e:                                        # noqa: BLE001
            print(f"  ⚠ mẫu người viết: không đọc được board {bs} ({type(e).__name__}) — bỏ qua board này")
    mau, bank = [], []
    for c in cards:
        ln = (lists.get(c.get("idList")) or "").lower()
        if not any(d in ln for d in dat):
            continue
        desc = c.get("desc") or ""
        if len(desc) < min_desc or _MAY_VIET.search(desc) or not _NGUOI_VIET.search(desc):
            continue
        mau.append({"name": c.get("name", ""), "list": lists.get(c.get("idList")), "desc": desc[:4000]})
        m = _SCALE.search(desc)
        if m:
            for ln2 in m.group(1).splitlines():
                t = ln2.strip().lstrip("-•* ").strip()
                if 3 <= len(t) <= 60:
                    bank.append(Signal(ref=f"HUMAN:{canon(t)[:36]}", kind="bank", label=t, evidence="HYPOTHESIS",
                                       source=f"board {tcfg['board']} · {c.get('name','')} · người viết 'Có thể scale'",
                                       as_of="", score=6.0,
                                       note=f"đội đã ghi hướng mở rộng cho mẫu đã lên: {t}"))
        if len(mau) >= gioi_han:
            break
    health = [f"· mẫu người viết: {len(mau)} thẻ đã lên/đã duyệt có mô tả ≥{min_desc} ký tự · "
              f"{len(bank)} hướng mở rộng đội tự ghi → tín hiệu HUMAN:"]
    return mau, bank, health


def nhan_may_duyet(brand) -> tuple[list, list]:
    """Đọc NHÃN do máy duyệt km_duyet 2.0 gắn trên board — vòng phản hồi engine vẫn thiếu.

    Bàn giao 30/09: mỗi card được gắn một trong «Claude ĐẠT» · «Need Fix» · «Loại - Pháp lý» ·
    «Loại - Chép đối thủ» · «Loại - Trùng» · «Loại - Kỹ thuật» · «Loại - Sai chữ/dữ kiện» · «ĐỂ DÀNH»,
    kèm comment "Tiêu chí cổng 6 dính: …". Trước đây engine chỉ đoán được qua TÊN LIST; nhãn nói rõ
    LÝ DO, và lý do mới là thứ dạy được. Trả (tín hiệu, health).
    """
    tcfg = brand.raw.get("trello") or {}
    if not tcfg.get("board"):
        return [], []
    lists, cards = fetch_board_cards(tcfg["board"])
    dem = collections.Counter()
    ly_do = collections.Counter()
    for c in cards:
        for l in (c.get("labels") or []):
            n = (l.get("name") or "").strip()
            if not n:
                continue
            u = n.lower()
            if "đạt" in u or "dat" == u:
                dem["dat"] += 1
            elif "need fix" in u or "fix" in u:
                dem["fix"] += 1
            elif "để dành" in u or "de danh" in u:
                dem["de_danh"] += 1
            elif u.startswith("loại") or u.startswith("loai"):
                dem["loai"] += 1
                ly_do[n] += 1
    tong = sum(dem.values())
    if tong < 10:
        return [], [f"· nhãn máy duyệt: mới {tong} thẻ có nhãn — chưa đủ để rút tín hiệu"]
    items = []
    for ten, n in ly_do.most_common(6):
        items.append(Signal(ref=f"REJECT:{canon(_bo_dau(ten))[:36]}", kind="hook", label=ten, evidence="SIGNAL",
                            source=f"board {tcfg['board']} · nhãn km_duyet", as_of="",
                            score=-min(30.0, 100.0 * n / max(1, tong)),
                            note=f"máy duyệt loại {n}/{tong} thẻ vì «{ten}» — tránh ngay từ lúc sinh ý"))
    health = [f"· nhãn máy duyệt: {tong} thẻ — ĐẠT {dem['dat']} · Need Fix {dem['fix']} · "
              f"Loại {dem['loai']} · để dành {dem['de_danh']}"]
    return items, health


def pheu(brand) -> dict | None:
    """PHỄU thẻ engine trên board: sinh ra bao nhiêu, còn chờ bao nhiêu, đi tiếp bao nhiêu, bị bỏ bao nhiêu.

    Đo 30/09/2026, 13 ngày sau khi bật: Kinmireva 72 thẻ engine → 0 quyết định; Gerbera 100 → 0;
    GritFell 191 → 56 quyết định (45 bỏ, 11 đi tiếp). Không ai biết vì không có dòng nào đếm.
    Từ nay `idea_audit` in dòng này mỗi sáng — thẻ nằm im 13 ngày phải hiện ra ở ngày thứ 2.
    """
    tcfg = brand.raw.get("trello") or {}
    if not tcfg.get("board"):
        return None
    prefix = (tcfg.get("prefix") or "").strip()
    fcfg = tcfg.get("feedback") or {}
    hcfg = tcfg.get("history_lists") or {}
    ok = [x.lower() for x in fcfg.get("approved_lists", []) + hcfg.get("uploaded", [])]
    bo = [x.lower() for x in fcfg.get("rejected_lists", []) + hcfg.get("rejected", [])]
    lists, cards = fetch_board_cards(tcfg["board"])
    tong = cho = di = loai = 0
    theo_list: dict = {}
    theo_layout: dict = {}         # 2.39.0: {layout: [duyệt, bỏ, chờ]} — đọc "Kiểu in: X" trên thẻ
    for c in cards:
        n = c.get("name") or ""
        if prefix and not n.startswith(prefix) and not (_la_the_cua(c, prefix) and SIG_RE.search(c.get("desc") or "")):
            continue
        tong += 1
        ln = (lists.get(c.get("idList")) or "")
        theo_list[ln] = theo_list.get(ln, 0) + 1
        l = ln.lower()
        m_lay = _LAYOUT_RE.search(c.get("desc") or "")
        tl = theo_layout.setdefault(m_lay.group(1) if m_lay else "?", [0, 0, 0])
        if c.get("closed") or any(x in l for x in bo):   # 2.35.5: archive = loại, như classify()
            loai += 1
            tl[1] += 1
        elif any(x in l for x in ok):
            di += 1
            tl[0] += 1
        else:
            cho += 1
            tl[2] += 1
    return {"tong": tong, "cho": cho, "di_tiep": di, "loai": loai, "theo_list": theo_list, "theo_layout": theo_layout}


_LAYOUT_RE = re.compile(r"Kiểu in:\s*([A-Z_]+)")


def dong_theo_layout(theo_layout: dict) -> str:
    """2.39.0 — đo TỰ ĐỘNG tỉ lệ duyệt theo kiểu in mỗi sáng. Trước đây muốn biết layout nào ăn phải có
    người đọc tay cả board (GritFell 03/10: FRONT_BACK 5/60 = 8% trong khi chiếm 20% slot). Chỉ ĐO, không tự
    chỉnh layout_mix — ngưỡng do máy tự đặt rồi tự áp là vòng tự nuôi (luật L3)."""
    parts = []
    for lay, (a, b, c) in sorted(theo_layout.items(), key=lambda kv: -(kv[1][0] + kv[1][1])):
        q = a + b
        parts.append(f"{lay} {a}/{q}" + (f" ({100 * a // q}%)" if q else "") + (f" +{c} chờ" if c else ""))
    return " · ".join(parts)


def collect(brand, today: date) -> dict:
    """Đọc board, gom theo chủ thể. Trả {subject: {approved, rejected, stale, pending}} + thống kê."""
    tcfg = brand.raw.get("trello") or {}
    fcfg = tcfg.get("feedback") or {}
    board = tcfg.get("board")
    if not board:
        raise FeedbackError("cartridge chưa khai trello.board")
    prefix = tcfg.get("prefix", "[2D]")
    fcfg = merged_lists(tcfg)
    lists, cards = fetch_board_cards(board)
    by_subject: dict = {}
    by_sig: dict = {}
    seen = 0
    for c in cards:
        # 2.35.5: nhận thẻ engine bằng CHỮ KÝ trong mô tả, không bằng tiền tố tên. Người làm đổi tên
        # thẻ khi đưa vào sản xuất (`[2D] …` → `PM-PB0576`) — thẻ duy nhất của engine đi tới Chờ Upload
        # (01/10) vì thế vô hình với vòng học: thành công thật duy nhất bị đếm 0.
        if not _la_the_cua(c, prefix):
            continue
        m = SIG_RE.search(c.get("desc") or "")
        if not m:
            continue
        sig = m.group(1).strip()
        if not sig.startswith(brand.brand + "|"):
            continue
        seen += 1
        verdict = classify(c, lists.get(c.get("idList"), ""), fcfg, today)
        by_sig[sig] = verdict
        subj = subject_of(sig)
        if subj:
            d = by_subject.setdefault(subj, {"approved": 0, "rejected": 0, "stale": 0, "pending": 0})
            d[verdict] += 1
    return {"brand": brand.brand, "as_of": today.isoformat(), "cards_seen": seen,
            "by_subject": by_subject, "by_sig": by_sig}


def score(fb: dict | None, subject: str | None) -> float:
    """Điểm ưu tiên cho một chủ thể: duyệt +1, bỏ -1, tồn -0.5. Không có dữ liệu = 0."""
    if not fb or not subject:
        return 0.0
    d = (fb.get("by_subject") or {}).get(subject.lower())
    if not d:
        return 0.0
    return d["approved"] * 1.0 - d["rejected"] * 1.0 - d["stale"] * 0.5


def score_for_label(fb: dict | None, label: str) -> float:
    """Điểm cho một NHÃN tín hiệu (vd 'MUSKY-FIGURE-EIGHT-2026', 'wood duck'): khớp chủ thể
    theo TỪ, lấy điểm mạnh nhất. 'musky' trong board khớp cả GAP:musky lẫn LEDGER:MUSKY-…"""
    if not fb or not label:
        return 0.0
    toks = {t for t in re.split(r"[^a-z0-9]+", str(label).lower()) if t}
    joined = "_".join(sorted(toks))
    best = 0.0
    for subj in (fb.get("by_subject") or {}):
        st = {t for t in subj.split("_") if t}
        if subj == joined or st <= toks:
            v = score(fb, subj)
            if abs(v) > abs(best):
                best = v
    return best


def path(home: Path, brand: str) -> Path:
    return home / "feedback" / f"{brand}.json"


def save(home: Path, fb: dict) -> Path:
    p = path(home, fb["brand"])
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(fb, ensure_ascii=False, indent=1), encoding="utf-8")
    os.replace(tmp, p)
    return p


def load(home: Path, brand: str) -> dict | None:
    p = path(home, brand)
    if not p.exists():
        return None
    return json.loads(p.read_text(encoding="utf-8"))


def summary_lines(fb: dict | None) -> list:
    if not fb:
        return ["· chưa có phản hồi từ board — chưa đọc được hoặc chưa có thẻ [2D] nào"]
    tot = {"approved": 0, "rejected": 0, "stale": 0, "pending": 0}
    for d in fb["by_subject"].values():
        for k in tot:
            tot[k] += d[k]
    out = [f"· phản hồi board ({fb['as_of']}): {fb['cards_seen']} thẻ · duyệt {tot['approved']} · bỏ {tot['rejected']}"
           f" · tồn>7d {tot['stale']} · chờ {tot['pending']}"]
    ranked = sorted(fb["by_subject"].items(), key=lambda kv: -score(fb, kv[0]))
    ups = [s for s, d in ranked if score(fb, s) > 0][:5]
    downs = [s for s, d in ranked if score(fb, s) < 0][-5:]
    if ups:
        out.append("  ↑ được duyệt: " + ", ".join(ups))
    if downs:
        out.append("  ↓ bị bỏ/tồn: " + ", ".join(downs))
    if fb["cards_seen"] and tot["approved"] == 0 and tot["rejected"] == 0:
        out.append("  ⚠ chưa có thẻ nào được kéo đi hay archive — người duyệt chưa động vào board, bộ não đang chạy mù")
    return out


def _put(path: str, params: dict, timeout: int = 30):
    k, t = _creds()
    body = urllib.parse.urlencode({**params, "key": k, "token": t}).encode()
    req = urllib.request.Request(f"{API}{path}", data=body, method="PUT",
                                 headers={"content-type": "application/x-www-form-urlencoded"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        raise FeedbackError(f"Trello HTTP {e.code} tại {path}: {e.read()[:200]!r}") from e


def archive_stale(brand, today: date, dry_run: bool = False) -> dict:
    """Dọn board: thẻ [2D] của brand này còn nằm ở list ý tưởng quá archive_stale_after_days
    thì archive (KHÔNG xoá — archive mở lại được). Không đụng thẻ người tạo, không đụng list khác.
    Mục tiêu: 20 thẻ/ngày không ai dọn thì 2 tuần thành 280 thẻ chết."""
    tcfg = brand.raw.get("trello") or {}
    fcfg = tcfg.get("feedback") or {}
    days = int(fcfg.get("archive_stale_after_days", 0) or 0)
    if days <= 0:
        return {"archived": [], "skipped": "archive_stale_after_days = 0 (tắt)"}
    prefix = tcfg.get("prefix", "[2D]")
    lists, cards = fetch_board_cards(tcfg["board"])
    done, failed = [], []
    for c in cards:
        if c.get("closed") or not c.get("name", "").startswith(prefix):
            continue
        ln = lists.get(c.get("idList"), "").lower()
        if not any(i.lower() in ln for i in fcfg.get("idea_lists", [])):
            continue
        # 2.35.5: so khớp CHUỖI CON — "Idea" khớp cả «Duyệt Idea». Không chặn chỗ này thì máy dọn sẽ
        # archive thẻ ĐÃ DUYỆT sau 14 ngày, và archive = bị loại → quyết định duyệt bị lật thành loại.
        mc = merged_lists(tcfg)
        if any(x.lower() in ln for x in mc["approved_lists"] + mc["rejected_lists"]):
            continue
        m = SIG_RE.search(c.get("desc") or "")
        if not m or not m.group(1).startswith(brand.brand + "|"):
            continue
        try:
            d = datetime.fromisoformat(c.get("dateLastActivity", "").replace("Z", "+00:00")).date()
        except ValueError:
            continue
        if (today - d).days < days:
            continue
        if dry_run:
            done.append(c["name"])
            continue
        try:
            _put(f"/cards/{c['id']}", {"closed": "true"})
            done.append(c["name"])
        except FeedbackError as e:
            failed.append(f"{c['name']}: {e}")
    return {"archived": done, "failed": failed, "days": days, "dry_run": dry_run}
